  ('78193727-18df-5953-8a2c-35c3e57c83ea', 'Studio full nội thất cao cấp tại Xã Đàn, Đống Đa', 'Studio hiện đại khép kín, đầy đủ điều hòa, nóng lạnh, giường nệm, tủ áo, bếp riêng. Giờ giấc tự do, bảo vệ 24/7, thang máy tốc độ cao. Địa chỉ: Xã Đàn, Nam Đồng, Quận Đống Đa, Hà Nội. Điện nước giá nhà nước, thanh toán linh hoạt.', 4200000, 18.0, 'Đống Đa', 'Số 162, Xã Đàn, Nam Đồng, Quận Đống Đa, Hà Nội', ARRAY['https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&w=800&q=80'], true, '2026-09-15T08:00:00Z'),
  ('28a617db-9cae-53c7-ab0f-7462385ee88b', 'Phòng trọ khép kín ban công thoáng mát tại Chùa Lộc, Đống Đa', 'Phòng rộng rãi có ban công đón nắng gió tự nhiên. Vệ sinh khép kín sạch sẽ, có sẵn máy giặt chung, wifi tốc độ cao, camera an ninh. Địa chỉ: Chùa Lộc, Láng Thượng, Quận Đống Đa, Hà Nội. Điện nước giá nhà nước, thanh toán linh hoạt.', 2800000, 25.0, 'Đống Đa', 'Số 112, Chùa Lộc, Láng Thượng, Quận Đống Đa, Hà Nội', ARRAY['https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=800&q=80'], true, '2026-09-15T08:00:00Z'),
  ('d6705afb-86eb-5925-ae2b-bb61aff60de6', 'Chung cư mini cao cấp có thang máy tại Tôn Đức Thắng, Đống Đa', 'Căn hộ mini thiết kế thông minh, nội thất gỗ sang trọng. Khu dân trí cao, an ninh tuyệt đối, bãi đỗ xe rộng rãi, có khóa vân tay ra vào. Địa chỉ: Tôn Đức Thắng, Hàng Bột, Quận Đống Đa, Hà Nội. Điện nước giá nhà nước, thanh toán linh hoạt.', 4200000, 25.0, 'Đống Đa', 'Số 105, Tôn Đức Thắng, Hàng Bột, Quận Đống Đa, Hà Nội', ARRAY['https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1536376072261-38c75010e6c9?auto=format&fit=crop&w=800&q=80'], true, '2026-09-15T08:00:00Z'),
