  ('6515b4a9-d47c-58c2-8345-8bea6a92ca1e', 'Phòng trọ khép kín ban công thoáng mát tại Định Công, Hoàng Mai', 'Phòng rộng rãi có ban công đón nắng gió tự nhiên. Vệ sinh khép kín sạch sẽ, có sẵn máy giặt chung, wifi tốc độ cao, camera an ninh. Địa chỉ: Định Công, Định Công, Quận Hoàng Mai, Hà Nội. Điện nước giá nhà nước, thanh toán linh hoạt.', 2600000, 18.0, 'Hoàng Mai', 'Số 25, Định Công, Định Công, Quận Hoàng Mai, Hà Nội', ARRAY['https://images.unsplash.com/photo-1505691938895-1758d7feb511?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1540518614846-7ede433c4ef3?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=800&q=80'], true, '2026-09-15T08:00:00Z'),
  ('4878e717-86f1-5177-acd4-bc3bcb0259a4', 'Chung cư mini cao cấp có thang máy tại Kim Đồng, Hoàng Mai', 'Căn hộ mini thiết kế thông minh, nội thất gỗ sang trọng. Khu dân trí cao, an ninh tuyệt đối, bãi đỗ xe rộng rãi, có khóa vân tay ra vào. Địa chỉ: Kim Đồng, Giáp Bát, Quận Hoàng Mai, Hà Nội. Điện nước giá nhà nước, thanh toán linh hoạt.', 2600000, 40.0, 'Hoàng Mai', 'Số 30, Kim Đồng, Giáp Bát, Quận Hoàng Mai, Hà Nội', ARRAY['https://images.unsplash.com/photo-1540518614846-7ede433c4ef3?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=800&q=80'], true, '2026-09-15T08:00:00Z'),
  ('a03b5f44-4c2b-5be9-9578-f47eca948d6a', 'Phòng gác lửng xinh xắn view đẹp tại Linh Đàm, Hoàng Mai', 'Phòng có gác lửng ngủ riêng biệt, tối ưu không gian sinh hoạt. Phù hợp cho 1-2 người ở hoặc sinh viên, người đi làm. Không chung chủ. Địa chỉ: Linh Đàm, Hoàng Liệt, Quận Hoàng Mai, Hà Nội. Điện nước giá nhà nước, thanh toán linh hoạt.', 2600000, 35.0, 'Hoàng Mai', 'Số 90, Linh Đàm, Hoàng Liệt, Quận Hoàng Mai, Hà Nội', ARRAY['https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80'], true, '2026-09-15T08:00:00Z'),
  ('f5c0aa59-83bd-5025-9417-ffee3f237ad8', 'Căn hộ 1 ngủ 1 khách riêng biệt tại Tam Trinh, Hoàng Mai', 'Thiết kế hiện đại chuẩn căn hộ dịch vụ: 1 phòng ngủ riêng, 1 phòng khách và bếp. Đầy đủ sofa, tivi, tủ lạnh, bếp từ. Thuận tiện đi lại. Địa chỉ: Tam Trinh, Mai Động, Quận Hoàng Mai, Hà Nội. Điện nước giá nhà nước, thanh toán linh hoạt.', 2200000, 22.5, 'Hoàng Mai', 'Số 84, Tam Trinh, Mai Động, Quận Hoàng Mai, Hà Nội', ARRAY['https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=800&q=80'], true, '2026-09-15T08:00:00Z');
